<script>
  import { preferHorizontalScroll as preferHorizontalScrollAction } from '@splendidlabz/utils/dom'
  import { init } from '../../utils'
  import { getTab, tablist } from './tabs.svelte.js'

  let {
    class: klass = '',
    target = null,
    scrollable = true,
    preferHorizontalScroll = true,
    preserveOutlines = true,

    // slots
    children,

    ...rest
  } = $props()

  let tab = $derived(getTab(target))
  let tablistClasses = $derived(getTablistClasses(tab))

  init(() => {
    if (!target) throw new Error('Tablist must have a target')
  })

  function getTablistClasses(tab) {
    if (!tab) return ''
    const { placement } = tab.state
    if (placement !== 'top') return ''

    const classes = []
    if (scrollable) classes.push('scrollable-horizontal')
    if (preferHorizontalScroll) classes.push('scrollable-preferHorizontalScroll')
    if (preserveOutlines) classes.push('preserve-outlines')
    return classes.join(' ')
  }
</script>

<div
  {...rest}
  class="tablist {tablistClasses} {klass}"
  role="tablist"
  {target}
  use:preferHorizontalScrollAction
  use:tablist={{
    state: {},
    options: rest,
  }}
>
  {@render children?.()}
</div>
